using Contoso.Orders;

namespace Contoso.Orders.Tests;

[TestClass]
public sealed class OrderServiceTests
{
    private readonly OrderService _service;

    public OrderServiceTests()
    {
        _service = new OrderService();
    }

    private static List<OrderItem> CreateItems(params (string name, decimal price, int qty)[] items) =>
        items.Select(i => new OrderItem { ProductName = i.name, Price = i.price, Quantity = i.qty }).ToList();

    #region CreateOrder - Happy Path

    [TestMethod]
    public void CreateOrder_WithValidItems_ReturnsOrderWithCorrectCustomerId()
    {
        // Arrange
        var items = CreateItems(("Widget", 10m, 2));

        // Act
        var order = _service.CreateOrder("cust-1", items);

        // Assert
        Assert.AreEqual("cust-1", order.CustomerId);
    }

    [TestMethod]
    public void CreateOrder_WithValidItems_ReturnsOrderWithNonEmptyId()
    {
        // Arrange
        var items = CreateItems(("Widget", 10m, 1));

        // Act
        var order = _service.CreateOrder("cust-1", items);

        // Assert
        Assert.IsNotNull(order.Id);
        Assert.IsNotEmpty(order.Id);
    }

    [TestMethod]
    public void CreateOrder_WithValidItems_AssignsItems()
    {
        // Arrange
        var items = CreateItems(("Widget", 10m, 2));

        // Act
        var order = _service.CreateOrder("cust-1", items);

        // Assert
        Assert.AreSame(items, order.Items);
    }

    [TestMethod]
    public void CreateOrder_WithSingleItem_CalculatesTotalCorrectly()
    {
        // Arrange
        var items = CreateItems(("Widget", 25.50m, 3));

        // Act
        var order = _service.CreateOrder("cust-1", items);

        // Assert
        Assert.AreEqual(76.50m, order.Total);
    }

    [TestMethod]
    public void CreateOrder_WithMultipleItems_SumsTotalAcrossAllItems()
    {
        // Arrange
        var items = CreateItems(("Widget", 10m, 2), ("Gadget", 5m, 4));

        // Act
        var order = _service.CreateOrder("cust-1", items);

        // Assert
        Assert.AreEqual(40m, order.Total);
    }

    [TestMethod]
    public void CreateOrder_SetsCreatedAtToRecentUtcTime()
    {
        // Arrange
        var items = CreateItems(("Widget", 10m, 1));
        var before = DateTime.UtcNow;

        // Act
        var order = _service.CreateOrder("cust-1", items);

        // Assert
        var after = DateTime.UtcNow;
        Assert.IsGreaterThan(before.AddSeconds(-1), order.CreatedAt);
        Assert.IsLessThan(after.AddSeconds(1), order.CreatedAt);
    }

    #endregion

    #region CreateOrder - Validation

    [TestMethod]
    public void CreateOrder_WithNullCustomerId_ThrowsArgumentNullException()
    {
        // Arrange
        var items = CreateItems(("Widget", 10m, 1));

        // Act & Assert
        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => _service.CreateOrder(null!, items));
        Assert.AreEqual("customerId", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithNullItems_ThrowsArgumentNullException()
    {
        // Act & Assert
        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => _service.CreateOrder("cust-1", null!));
        Assert.AreEqual("items", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithEmptyItems_ThrowsInvalidOperationException()
    {
        // Act & Assert
        var ex = Assert.ThrowsExactly<InvalidOperationException>(
            () => _service.CreateOrder("cust-1", []));
        Assert.Contains("no items", ex.Message, StringComparison.OrdinalIgnoreCase);
    }

    #endregion

    #region GetOrder

    [TestMethod]
    public void GetOrder_WithExistingId_ReturnsMatchingOrder()
    {
        // Arrange
        var items = CreateItems(("Widget", 10m, 1));
        var created = _service.CreateOrder("cust-1", items);

        // Act
        var retrieved = _service.GetOrder(created.Id);

        // Assert
        Assert.IsNotNull(retrieved);
        Assert.AreEqual(created.Id, retrieved.Id);
    }

    [TestMethod]
    public void GetOrder_WithNonExistentId_ReturnsNull()
    {
        // Act
        var result = _service.GetOrder("does-not-exist");

        // Assert
        Assert.IsNull(result);
    }

    [TestMethod]
    public void GetOrder_ReturnsSameObjectReference()
    {
        // Arrange
        var items = CreateItems(("Widget", 10m, 1));
        var created = _service.CreateOrder("cust-1", items);

        // Act
        var retrieved = _service.GetOrder(created.Id);

        // Assert
        Assert.AreSame(created, retrieved);
    }

    #endregion

    #region GetOrdersByCustomer

    [TestMethod]
    public void GetOrdersByCustomer_WithNoOrders_ReturnsEmptyList()
    {
        // Act
        var orders = _service.GetOrdersByCustomer("cust-999");

        // Assert
        Assert.IsEmpty(orders);
    }

    [TestMethod]
    public void GetOrdersByCustomer_WithOneOrder_ReturnsSingleOrder()
    {
        // Arrange
        var items = CreateItems(("Widget", 10m, 1));
        var created = _service.CreateOrder("cust-1", items);

        // Act
        var orders = _service.GetOrdersByCustomer("cust-1");

        // Assert
        var single = Assert.ContainsSingle(orders);
        Assert.AreEqual(created.Id, single.Id);
    }

    [TestMethod]
    public void GetOrdersByCustomer_WithMultipleOrders_ReturnsAllForCustomer()
    {
        // Arrange
        _service.CreateOrder("cust-1", CreateItems(("A", 10m, 1)));
        _service.CreateOrder("cust-1", CreateItems(("B", 20m, 1)));
        _service.CreateOrder("cust-2", CreateItems(("C", 30m, 1)));

        // Act
        var orders = _service.GetOrdersByCustomer("cust-1");

        // Assert
        Assert.HasCount(2, orders);
    }

    [TestMethod]
    public void GetOrdersByCustomer_DoesNotReturnOtherCustomersOrders()
    {
        // Arrange
        _service.CreateOrder("cust-1", CreateItems(("A", 10m, 1)));
        var otherOrder = _service.CreateOrder("cust-2", CreateItems(("B", 20m, 1)));

        // Act
        var orders = _service.GetOrdersByCustomer("cust-1");

        // Assert
        Assert.DoesNotContain(otherOrder, orders);
    }

    #endregion

    #region CreateOrder - Data-Driven Total Calculation

    [TestMethod]
    [DynamicData(nameof(TotalCalculationData))]
    public void CreateOrder_CalculatesExpectedTotal(
        string description, List<OrderItem> items, decimal expectedTotal)
    {
        // Act
        var order = _service.CreateOrder("cust-1", items);

        // Assert
        Assert.AreEqual(expectedTotal, order.Total);
    }

    public static IEnumerable<(string description, List<OrderItem> items, decimal expectedTotal)> TotalCalculationData =>
    [
        ("Single item, qty 1", CreateItems(("A", 10m, 1)), 10m),
        ("Single item, qty 5", CreateItems(("A", 10m, 5)), 50m),
        ("Two items", CreateItems(("A", 10m, 2), ("B", 5m, 3)), 35m),
        ("Zero price item", CreateItems(("Free", 0m, 10)), 0m),
        ("Decimal prices", CreateItems(("A", 9.99m, 2), ("B", 4.50m, 1)), 24.48m),
    ];

    #endregion
}

